package com.interviewiq.ai;

import com.fasterxml.jackson.databind.*;import com.interviewiq.domain.Question;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.util.*;

@Service public class GeminiAIService implements AIService {
 private final String key,model;private final RestClient client;private final ObjectMapper json;
 public GeminiAIService(@Value("${app.gemini.api-key:}") String key,@Value("${app.gemini.model:gemini-2.0-flash}") String model,ObjectMapper json){this.key=key;this.model=model;this.json=json;this.client=RestClient.builder().baseUrl("https://generativelanguage.googleapis.com/v1beta").build();}
 @Override public List<Question> generate(String role,String difficulty,List<String> topics,int count,List<String> types,String experience){if(key.isBlank())return List.of();String prompt="Create exactly "+count+" distinct interview practice questions for role "+role+", difficulty "+difficulty+", candidate experience "+experience+", topics "+topics+". Allowed types: "+types+". Return ONLY JSON {\"questions\":[{\"question\":string,\"type\":\"MCQ|TRUE_FALSE|TECHNICAL|BEHAVIORAL\",\"difficulty\":\"EASY|MEDIUM|HARD\",\"topic\":string,\"options\":string[],\"correctAnswer\":string|null,\"explanation\":string,\"expectedConcepts\":string[]}]}. MCQ requires 4 distinct options and exactly one correctAnswer matching an option. TRUE_FALSE options must be True and False. Technical and behavioral questions require expectedConcepts. No markdown.";try{JsonNode root=call(prompt);String text=root.path("candidates").path(0).path("content").path("parts").path(0).path("text").asText();JsonNode parsed=json.readTree(clean(text));JsonNode array=parsed.path("questions");if(!array.isArray()||array.size()!=count)throw new IllegalArgumentException("Question count mismatch");List<Question> out=new ArrayList<>();for(JsonNode n:array){String q=n.path("question").asText("").trim(),type=n.path("type").asText("").toUpperCase(),topic=n.path("topic").asText("").trim(),diff=n.path("difficulty").asText("").toUpperCase(),explanation=n.path("explanation").asText("").trim();List<String> options=new ArrayList<>();n.path("options").forEach(v->options.add(v.asText().trim()));String answer=n.path("correctAnswer").isNull()?null:n.path("correctAnswer").asText();String concepts=join(n.path("expectedConcepts"));if(q.isBlank()||topic.isBlank()||!Set.of("MCQ","TRUE_FALSE","TECHNICAL","BEHAVIORAL").contains(type)||!Set.of("EASY","MEDIUM","HARD").contains(diff)||explanation.isBlank())throw new IllegalArgumentException("Invalid question");if((type.equals("MCQ")&&(options.size()<2||answer==null||options.stream().filter(answer::equalsIgnoreCase).count()!=1))||(type.equals("TRUE_FALSE")&&(!options.equals(List.of("True","False"))||answer==null))||((type.equals("TECHNICAL")||type.equals("BEHAVIORAL"))&&concepts.isBlank()))throw new IllegalArgumentException("Invalid question schema");out.add(new Question(q,type,topic,diff,options,answer,explanation,concepts));}return out;}catch(Exception ex){return List.of();}}
 @Override public Map<String,Object> evaluate(String question,String expectedConcepts,String answer,boolean behavioral){if(key.isBlank())return Map.of();String prompt="Evaluate this "+(behavioral?"behavioral interview":"technical")+" text answer. This is educational feedback, not a psychological assessment. Score each category 0-10 with a fixed rubric: correctness/relevance 0-10, completeness 0-10, depth/structure 0-10, clarity 0-10. For behavioral answers, use observable text evidence only. Question: "+question+". Expected concepts/criteria: "+expectedConcepts+". Candidate answer: "+answer+". Return ONLY JSON with score (0-100), feedback (string), strengths (string array), improvements (string array), missingConcepts (string array).";try{JsonNode data=call(prompt);String text=clean(data.path("candidates").path(0).path("content").path("parts").path(0).path("text").asText());JsonNode parsed=json.readTree(text);int score=Math.max(0,Math.min(100,parsed.path("score").asInt(-1)));if(score<0||!parsed.path("feedback").isTextual())return Map.of();Map<String,Object> out=new LinkedHashMap<>();out.put("score",score);out.put("feedback",parsed.path("feedback").asText());out.put("strengths",strings(parsed.path("strengths")));out.put("improvements",strings(parsed.path("improvements")));out.put("missingConcepts",strings(parsed.path("missingConcepts")));return out;}catch(Exception ex){return Map.of();}}
 private JsonNode call(String prompt){Map<String,Object> body=Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text",prompt)))),"generationConfig",Map.of("responseMimeType","application/json","temperature",0.25));return client.post().uri("/models/{model}:generateContent?key={key}",model,key).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(JsonNode.class);}
 private String clean(String s){return s==null?"":s.trim().replaceAll("^```(?:json)?\\s*","").replaceAll("\\s*```$","");}
 private String join(JsonNode n){if(!n.isArray())return "";List<String> a=new ArrayList<>();n.forEach(x->{if(x.isTextual()&&!x.asText().isBlank())a.add(x.asText().trim());});return String.join(", ",a);}
 private List<String> strings(JsonNode n){List<String> a=new ArrayList<>();if(n.isArray())n.forEach(x->{if(x.isTextual())a.add(x.asText());});return a;}
}
